// BASE: unit test — fast, isolated business logic
@ExtendWith(MockitoExtension.class)
class OrderServiceTest {
    @Mock private OrderRepository repository;
    @InjectMocks private OrderService service;

    @Test
    void shouldApplyMemberDiscount() {
        var order = new Order(1L, "item", 100.0);
        when(repository.findById(1L)).thenReturn(Optional.of(order));
        assertEquals(90.0, service.calculateTotal(1L, true)); // 10% off
    }
}

// MIDDLE: slice test — controller layer with MockMvc
@WebMvcTest(OrderController.class)
class OrderControllerTest {
    @Autowired private MockMvc mockMvc;
    @MockBean private OrderService service; // service still mocked

    @Test
    void shouldReturnOrderTotal() throws Exception {
        when(service.calculateTotal(1L, true)).thenReturn(90.0);
        mockMvc.perform(get("/orders/1/total"))
               .andExpect(status().isOk())
               .andExpect(jsonPath("$.total").value(90.0));
    }
}

// TOP: full integration test — end-to-end
@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
class OrderEndToEndTest {
    @Autowired private TestRestTemplate restTemplate;

    @Test
    void shouldCreateAndRetrieveOrder() { // full flow: API to service to database
        var response = restTemplate.postForEntity("/orders",
            new Order(null, "item", 100.0), Order.class);
        assertEquals(HttpStatus.CREATED, response.getStatusCode());
    }
}
