@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
class OrderIntegrationTest {
    @Autowired private TestRestTemplate restTemplate;  // real HTTP client
    @Autowired private OrderRepository orderRepository; // real repository

    @Test
    void shouldCreateOrderEndToEnd() {
        var request = new CreateOrderRequest("Laptop", 1500.0);

        var response = restTemplate.postForEntity("/orders", request, Order.class);

        assertEquals(HttpStatus.CREATED, response.getStatusCode());
        var savedOrder = orderRepository.findById(response.getBody().getId());
        assertTrue(savedOrder.isPresent()); // verifies database persistence
    }
}
