class PaymentServiceTest {
    @Mock // Mockito's mock, not Spring's
    private PaymentGateway paymentGateway;

    @Mock
    private OrderRepository orderRepository;

    @InjectMocks // Mockito injects mocks, not Spring
    private PaymentService paymentService;

    @Test
    void shouldProcessPaymentSuccessfully() {
        var order = new Order(1L, "Laptop", 1500.0);
        when(paymentGateway.charge(1500.0)).thenReturn(true);

        var result = paymentService.processPayment(order); // pure logic test

        assertTrue(result);
        verify(paymentGateway).charge(1500.0); // no Spring context involved
    }
}
